/** The example workflows, file name → text, written as `.sim/examples/<file>`: together one correct example of each common block. */
export const COOKBOOK_EXAMPLES: Readonly<Record<string, string>> = {"agents.ts":"// @sim-sdk 1\nimport {\n  agent,\n  childWorkflow,\n  credential,\n  customTool,\n  env,\n  mcp,\n  parallel,\n  response,\n  router,\n  runWorkflow,\n  slack,\n  t,\n  trigger,\n  workflow,\n} from \u0027@sim/workflow-sdk\u0027\n\n// An example to copy from, not a workflow of yours: `lookup-order`, `linear`, `ops-slack`,\n// `enrich-lead` and ANTHROPIC_API_KEY stand in for this workspace\u0027s resources\n// (.sim/sdk/workspace.d.ts; `sim workflows source resources` lists the real keys).\nexport default workflow(\n  \u0027Cookbook: agents and subflows\u0027,\n  { description: \u0027Router, agent tools, a child workflow and a parallel fan-out.\u0027 },\n  () => {\n    const start = trigger.start(\u0027Start\u0027, {\n      inputFormat: { message: \u0027string\u0027, email: \u0027string\u0027, domains: \u0027array\u0027 },\n    })\n\n    // Router: the model picks one route by its description; wire with triage.<route>.to(...).\n    const triage = router(\u0027Triage\u0027, {\n      context: start.message,\n      model: \u0027claude-sonnet-4-6\u0027,\n      apiKey: env.ANTHROPIC_API_KEY,\n      routes: {\n        support: \u0027A customer asking about an existing order\u0027,\n        sales: \u0027A prospect asking about pricing or a demo\u0027,\n      },\n    })\n\n    // Agent tools: a workspace custom tool, one tool of an MCP server, an integration operation\n    // (<service>.tool.<operation>; the params given here are fixed, the model fills the rest) and\n    // another workflow.\n    const support = agent(\u0027Support Agent\u0027, {\n      model: \u0027claude-sonnet-4-6\u0027,\n      apiKey: env.ANTHROPIC_API_KEY,\n      messages: [\n        { role: \u0027system\u0027, content: \u0027Answer the customer. Use your tools when they help.\u0027 },\n        { role: \u0027user\u0027, content: start.message },\n      ],\n      tools: [\n        customTool(\u0027lookup-order\u0027),\n        mcp(\u0027linear\u0027).tool(\u0027create_issue\u0027),\n        slack.tool.sendMessage({ credential: credential(\u0027ops-slack\u0027), channel: \u0027support-urgent\u0027 }),\n        childWorkflow(\u0027enrich-lead\u0027).asTool(),\n      ],\n    })\n\n    // Child workflow: inputMapping is checked against the child\u0027s start inputs. Its output is\n    // enrich.result (untyped JSON): the child\u0027s response block output, so a field of the child\u0027s\n    // response body is enrich.result.data.<field>.\n    const enrich = runWorkflow(\u0027Enrich Lead\u0027, {\n      workflowId: childWorkflow(\u0027enrich-lead\u0027),\n      inputMapping: { email: start.email },\n    })\n\n    // Parallel: one branch per item, run at once. p.currentItem is the item and p.index its\n    // position; each.results lists every branch\u0027s output once all finish. (loop.forEach is the\n    // sequential form.) In a function code file inside the body, the same values are\n    // $ref.parallel.currentItem and $ref.parallel.index.\n    const each = parallel.collection(\u0027Each Domain\u0027, { collection: start.domains }, (p) => {\n      const brief = agent(\u0027Company Brief\u0027, {\n        model: \u0027claude-sonnet-4-6\u0027,\n        apiKey: env.ANTHROPIC_API_KEY,\n        messages: [{ role: \u0027user\u0027, content: t`Describe ${p.currentItem} in two sentences.` }],\n      })\n      p.to(brief)\n    })\n\n    const answer = response(\u0027Answer\u0027, { body: { answer: support.content } })\n    const briefs = response(\u0027Briefs\u0027, {\n      body: { lead: t`${enrich.result}`, briefs: t`${each.results}` },\n    })\n\n    start.to(triage)\n    triage.support.to(support)\n    support.to(answer)\n    triage.sales.to(enrich)\n    enrich.to(each)\n    each.to(briefs)\n  }\n)\n","cookbook.ts":"// @sim-sdk 1\nimport {\n  agent,\n  condition,\n  credential,\n  env,\n  fn,\n  human,\n  js,\n  knowledge,\n  knowledgeBase,\n  loop,\n  response,\n  slack,\n  t,\n  table,\n  trigger,\n  workflow,\n} from \u0027@sim/workflow-sdk\u0027\n\n// An example to copy from, not a workflow of yours: `orders`, `policies`, `ops-slack` and\n// ANTHROPIC_API_KEY stand in for this workspace\u0027s resources. `sim workflows source resources`\n// lists the real keys, and .sim/sdk/workspace.d.ts types them.\nexport default workflow(\u0027Cookbook\u0027, { description: \u0027One example of each common block.\u0027 }, () => {\n  // Triggers: trigger.start (API/manual input), trigger.schedule, trigger.webhook.\n  const start = trigger.start(\u0027Start\u0027, { inputFormat: { orderId: \u0027string\u0027, amount: \u0027number\u0027 } })\n  const nightly = trigger.schedule(\u0027Nightly\u0027, {\n    scheduleType: \u0027daily\u0027,\n    dailyTime: \u002702:00\u0027,\n    timezone: \u0027UTC\u0027,\n  })\n\n  // Agent: structured output via responseFormat; its fields become outputs (check.risk).\n  // apiKey: needed on self-hosted Sim; hosted Sim supplies one.\n  const check = agent(\u0027Check Order\u0027, {\n    model: \u0027claude-sonnet-4-6\u0027,\n    apiKey: env.ANTHROPIC_API_KEY,\n    messages: [\n      { role: \u0027system\u0027, content: \u0027Rate the fraud risk of an order as low, med or high.\u0027 },\n      { role: \u0027user\u0027, content: t`Order ${start.orderId} for ${start.amount}` },\n    ],\n    responseFormat: {\n      name: \u0027risk\u0027,\n      strict: true,\n      schema: {\n        type: \u0027object\u0027,\n        properties: {\n          risk: { type: \u0027string\u0027, enum: [\u0027low\u0027, \u0027med\u0027, \u0027high\u0027] },\n          reason: { type: \u0027string\u0027 },\n        },\n        required: [\u0027risk\u0027, \u0027reason\u0027],\n        additionalProperties: false,\n      },\n    },\n  })\n\n  // Condition: one branch per key, `else: true` last; wire with route.<key>.to(...).\n  const route = condition(\u0027Route Risk\u0027, {\n    high: js`${check.risk} === \u0027high\u0027`,\n    med: js`${check.risk} === \u0027med\u0027`,\n    else: true,\n  })\n\n  // Function: inline JavaScript; reference outputs with ${...}. Result is fn.result.\n  const shape = fn(\u0027Shape\u0027, {\n    code: js`return { id: ${start.orderId}, cents: Math.round(${start.amount} * 100) }`,\n  })\n\n  // Tables: query rows (each row is { id, data: { column } }) and write one.\n  const recent = table.queryRows(\u0027Recent Orders\u0027, {\n    tableId: table(\u0027orders\u0027),\n    filterInput: { all: [{ field: \u0027status\u0027, op: \u0027eq\u0027, value: \u0027open\u0027 }] },\n    limit: 50,\n  })\n  // Upsert: updates the row whose conflictColumn (a unique column, by name) matches data, else\n  // inserts one, so a second run for the same order updates it. table.insertRow takes the same\n  // data without conflictColumn and adds a row every run. data is keyed by column name: a column\n  // declared as `phone: column.string({ name: \u0027mobile\u0027 })` is written as { mobile: ... }.\n  const save = table.upsertRow(\u0027Save Order\u0027, {\n    tableId: table(\u0027orders\u0027),\n    data: { orderId: start.orderId, status: \u0027open\u0027 },\n    conflictColumn: \u0027orderId\u0027,\n  })\n\n  // Knowledge base search: results is the list of matching chunks.\n  const docs = knowledge.search(\u0027Policy Search\u0027, {\n    knowledgeBaseId: knowledgeBase(\u0027policies\u0027),\n    query: check.reason,\n    topK: 3,\n  })\n\n  // Slack: a saved credential by key (see .sim/sdk/workspace.d.ts).\n  const alert = slack.sendMessage(\u0027Alert Ops\u0027, {\n    credential: credential(\u0027ops-slack\u0027),\n    destinationType: \u0027channel\u0027,\n    channel: \u0027ops-alerts\u0027,\n    messageFormat: \u0027text\u0027,\n    text: t`High-risk order ${start.orderId}: ${check.reason}`,\n  })\n\n  // Human in the loop: inputFormat is the form; answers are approval.submission.<field>.\n  const approval = human(\u0027Manager Review\u0027, {\n    builderData: [{ name: \u0027orderId\u0027, type: \u0027string\u0027, value: start.orderId }],\n    inputFormat: { approved: { type: \u0027boolean\u0027, required: true }, note: \u0027string\u0027 },\n  })\n  const decided = condition(\u0027Approved\u0027, {\n    yes: js`${approval.submission.approved} === true`,\n    else: true,\n  })\n\n  // Loop over a list: p.currentItem is one element and p.index its position; the loop\u0027s results\n  // is the list of iteration outputs. In js`` code a reference is the value itself, not text\n  // spliced in: write it where an expression goes, never inside quotes (\u0027${x}\u0027 would give the\n  // JSON, quotes included). A function code file (code: codeFile(\u0027./functions/line.js\u0027)) reads\n  // other blocks as $ref.<block key>.<path> ($ref.recentorders.rows) and, inside the loop body,\n  // the iteration as $ref.loop.currentItem and $ref.loop.index.\n  const each = loop.forEach(\u0027Each Order\u0027, { collection: recent.rows }, (p) => {\n    const line = fn(\u0027Line\u0027, {\n      code: js`return ${p.currentItem.data.orderId} + \u0027: \u0027 + ${p.currentItem.data.status}`,\n    })\n    p.to(line)\n  })\n  const report = agent(\u0027Report\u0027, {\n    model: \u0027claude-sonnet-4-6\u0027,\n    apiKey: env.ANTHROPIC_API_KEY,\n    messages: [{ role: \u0027user\u0027, content: t`Summarize these orders in 3 lines:\\n${each.results}` }],\n  })\n  const post = slack.sendMessage(\u0027Post Report\u0027, {\n    credential: credential(\u0027ops-slack\u0027),\n    destinationType: \u0027channel\u0027,\n    channel: \u0027ops-daily\u0027,\n    messageFormat: \u0027text\u0027,\n    text: report.content,\n  })\n\n  // Response: the API reply body. Wrap an untyped value (fn.result.x) in t`` when it is text.\n  // body is the short form of the editor\u0027s JSON mode: { dataMode: \u0027json\u0027, data } as below.\n  const reply = response(\u0027Respond\u0027, { body: { risk: check.risk, id: t`${shape.result.id}` } })\n  const rejected = response(\u0027Respond Rejected\u0027, {\n    dataMode: \u0027json\u0027,\n    data: { status: \u0027rejected\u0027 },\n  })\n\n  // Wiring: a.to(b) chains; a block can fan out to several targets.\n  start.to(check)\n  check.to(save)\n  save.to(route)\n  route.high.to(alert)\n  alert.to(approval)\n  approval.to(decided)\n  decided.yes.to(shape)\n  decided.else.to(rejected)\n  route.med.to(docs)\n  docs.to(shape)\n  route.else.to(shape)\n  shape.to(reply)\n  nightly.to(recent)\n  recent.to(each)\n  each.to(report)\n  report.to(post)\n})\n","integrations.ts":"// @sim-sdk 1\nimport {\n  api,\n  credential,\n  env,\n  gmail,\n  response,\n  t,\n  table,\n  trigger,\n  workflow,\n} from \u0027@sim/workflow-sdk\u0027\n\n// An example to copy from, not a workflow of yours: `leads`, `ops-gmail`, CLEARBIT_KEY and\n// LEADS_WEBHOOK_TOKEN stand in for this workspace\u0027s resources (.sim/sdk/workspace.d.ts).\n// Integration builders are named by service, not block type: `gmail_v2` is `gmail.*`, and a\n// hidden older version lives under `legacy.*`. .sim/sdk/INDEX.md lists every builder.\nexport default workflow(\n  \u0027Cookbook: integrations\u0027,\n  { description: \u0027Webhook, weekday schedule, HTTP with headers, table update, Gmail, error path.\u0027 },\n  () => {\n    // Webhook trigger: inputFormat types the posted JSON fields (hook.leadId). With requireAuth\n    // the caller must send the token; keep it in an env var.\n    const hook = trigger.webhook(\u0027Lead Webhook\u0027, {\n      requireAuth: true,\n      token: env.LEADS_WEBHOOK_TOKEN,\n      inputFormat: { leadId: \u0027string\u0027, email: \u0027string\u0027, domain: \u0027string\u0027 },\n    })\n\n    // Schedule: no weekday preset exists, so scheduleType \u0027custom\u0027 takes a 5-field cron.\n    const weekdays = trigger.schedule(\u0027Weekdays 8am\u0027, {\n      scheduleType: \u0027custom\u0027,\n      cronExpression: \u00270 8 * * 1-5\u0027,\n      timezone: \u0027America/New_York\u0027,\n    })\n\n    // HTTP request: headers (and query params) are table rows, { cells: { Key, Value } }.\n    const lookup = api(\u0027Company Lookup\u0027, {\n      url: t`https://company.clearbit.com/v2/companies/find?domain=${hook.domain}`,\n      method: \u0027GET\u0027,\n      headers: [{ cells: { Key: \u0027Authorization\u0027, Value: t`Bearer ${env.CLEARBIT_KEY}` } }],\n    })\n\n    // Update one row by id: data holds only the columns to change. lookup.data is untyped JSON,\n    // so a text field from it is wrapped in t``.\n    const save = table.updateRowById(\u0027Save Company\u0027, {\n      tableId: table(\u0027leads\u0027),\n      rowId: hook.leadId,\n      data: { company: t`${lookup.data.name}`, enriched: true },\n    })\n\n    // Gmail (gmail_v2): send one email with a saved Google credential.\n    const welcome = gmail.sendEmail(\u0027Welcome Email\u0027, {\n      credential: credential(\u0027ops-gmail\u0027),\n      to: hook.email,\n      subject: \u0027Welcome aboard\u0027,\n      body: t`Thanks for signing up from ${hook.domain}.`,\n    })\n\n    // Query rows, then email them as one digest. A typed column filter: { field, op, value }.\n    const pending = table.queryRows(\u0027Pending Leads\u0027, {\n      tableId: table(\u0027leads\u0027),\n      filterInput: { all: [{ field: \u0027enriched\u0027, op: \u0027eq\u0027, value: false }] },\n      limit: 100,\n    })\n    const digest = gmail.sendEmail(\u0027Pending Digest\u0027, {\n      credential: credential(\u0027ops-gmail\u0027),\n      to: \u0027ops@example.com\u0027,\n      subject: \u0027Leads still to enrich\u0027,\n      body: t`${pending.rows}`,\n    })\n\n    // Error path: x.onError(y) runs y when x fails, instead of failing the run; y reads the\n    // failure message as x.error.\n    const failed = response(\u0027Lookup Failed\u0027, {\n      body: { ok: false, error: lookup.error },\n      status: 502,\n    })\n    const done = response(\u0027Done\u0027, { body: { ok: true, row: save.row } })\n\n    hook.to(lookup)\n    lookup.to(save)\n    lookup.onError(failed)\n    save.to(welcome)\n    welcome.to(done)\n    weekdays.to(pending)\n    pending.to(digest)\n  }\n)\n"}
